package com.autosphere.controller;
import com.autosphere.model.*;import com.autosphere.repository.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.Map;
@RestController @RequestMapping("/api/bookings") public class BookingController {private final BookingRepository bookings;private final VehicleRepository vehicles;public BookingController(BookingRepository b,VehicleRepository v){bookings=b;vehicles=v;}public record Request(@NotBlank String name,@Email String email,@NotBlank String phone,@NotNull Long vehicleId,@NotNull LocalDate bookingDate,@NotBlank String slotTime,@NotBlank String showroom,@AssertTrue boolean consentGiven){}@GetMapping("/availability") public java.util.List<Map<String,Object>> availability(@RequestParam Long vehicleId,@RequestParam LocalDate date){String[] slots={"10:00","11:00","12:00","14:00","15:00","16:00"};return java.util.Arrays.stream(slots).map(slot->Map.<String,Object>of("slotTime",slot,"available",!bookings.existsByVehicleIdAndBookingDateAndSlotTime(vehicleId,date,slot))).toList();}@PostMapping public ResponseEntity<?> create(@Valid @RequestBody Request r){if(r.bookingDate().isBefore(LocalDate.now()))return ResponseEntity.badRequest().body(Map.of("message","Choose a future date."));Vehicle v=vehicles.findById(r.vehicleId()).orElse(null);if(v==null)return ResponseEntity.badRequest().body(Map.of("message","Vehicle not found."));TestDriveBooking b=new TestDriveBooking();b.name=r.name();b.email=r.email();b.phone=r.phone();b.vehicle=v;b.bookingDate=r.bookingDate();b.slotTime=r.slotTime();b.showroom=r.showroom();b.consentGiven=r.consentGiven();try{return ResponseEntity.status(HttpStatus.CREATED).body(bookings.save(b));}catch(DataIntegrityViolationException ex){return ResponseEntity.status(409).body(Map.of("message","This vehicle slot has already been requested. Please choose another."));}}}
